use verus::prelude::*;

verus! {

    /// Linear search for `e` in `a`: returns the first index i with a[i] == e,
    /// or a.len() if none exists.
    pub fn linear_search(a: &Vec<i32>, e: i32) -> usize
        // 0 ≤ ret ≤ a.len()
        ensures |ret: usize| ret <= a.len()
        // If ret < a.len(), then a[ret] == e
        ensures |ret: usize| ret < a.len() ==> a.index(ret) == e
        // All positions before ret are ≠ e
        ensures |ret: usize| forall |j: usize| j < ret ==> a.index(j) != e
    {
        let mut i: usize = 0;
        // Scan until we either reach the end or find e
        while i < a.len() && a.index(i) != e
            invariant i <= a.len()
            invariant forall |j: usize| j < i ==> a.index(j) != e
            decreases a.len() - i
        {
            i += 1;
        }
        i
    }

}